    "\xFCretim projesi se\xE7ildi": "production projects selected",
    "Teklif Revizyonlar\u0131": "Quote Revisions",
    "Hen\xFCz kaydedilmi\u015F teklif revizyonu yok.": "No saved quote revisions yet.",
    "Mod\xFCl y\xFCkleniyor\u2026": "Loading module\u2026",
    "Sevkiyat hen\xFCz aktif de\u011Fil": "Shipping is not active yet",
    "Bu alan daha sonra kullan\u0131ma a\xE7\u0131lacakt\u0131r.": "This area will be available later.",
    "\u015Eematik teknik g\xF6r\xFCn\xFCm": "Schematic Technical View",
    "Araman\u0131zla e\u015Fle\u015Fen renk bulunamad\u0131.": "No colours match your search.",
    "\xB7 Karteladan Se\xE7": "\xB7 Choose from Colour Chart",
    "i\xE7in y\xFCzey se\xE7in.": "choose a surface finish for.",
    "Proje Olu\u015Ftur": "Create Project",
    "Yeni Project Master olu\u015Fturulmaz. Se\xE7ilen mevcut PRJ kayd\u0131 teknik proje olarak devam eder.": "No new project master is created. The selected existing project continues as a technical project.",
    "Hesab\u0131n\u0131z ba\u015Fka bir cihazda a\xE7\u0131ld\u0131\u011F\u0131 i\xE7in bu oturum sonland\u0131r\u0131ld\u0131.": "This session ended because your account was opened on another device.",
    "Offline review shell yaln\u0131z ayn\u0131-runtime/session registry davran\u0131\u015F\u0131n\u0131 g\xF6sterir. Ger\xE7ek cihazlar aras\u0131 enforcement \xFCretimde merkezi kimlik do\u011Frulama servisi taraf\u0131ndan yap\u0131lacakt\u0131r.": "This offline preview controls sessions within one browser only. Cross-device sign-in control needs a central authentication service in production.",
    "Bu Taray\u0131c\u0131": "This Browser",
    "Yeniden oynatmak i\xE7in logoya t\u0131klay\u0131n": "Click the logo to replay",
