    "Kredi Kart\u0131": "Credit Card",
    "\xC7ek": "Cheque",
    "Pe\u015Fin": "Cash / Upfront",
    "Cari ba\u015Far\u0131yla kaydedildi.": "Contact saved.",
    "CAR\u0130 B\u0130LG\u0130LER\u0130": "CONTACT DETAILS",
    "Belgelerde G\xF6r\xFCnen Firma Ad\u0131": "Company Name on Documents",
    "Cari Belge Ad\u0131": "Contact Document Name",
    "Firma / Cari Ad\u0131": "Company / Contact Name",
    "M\xFC\u015Fteri Cari Kodu": "Customer Account Code",
    "Tedarik\xE7i Cari Kodu": "Supplier Account Code",
    "CAR\u0130 YETK\u0130L\u0130LER\u0130": "CONTACT PEOPLE",
