    "\xC7izim penceresi bulunamad\u0131.": "The drawing window was not found.",
    "Bu karma sahne i\xE7in V76 \xFCretim re\xE7etesi tan\u0131ml\u0131 de\u011Fil. PDF / DXF / DAE \xE7izim \xE7\u0131kt\u0131lar\u0131 V29 motorundan al\u0131nabilir. Eksik \xFCretim paketi olu\u015Fturulmad\u0131.": "No production recipe is defined for this mixed scene. PDF, DXF and DAE drawings are available. No incomplete production package was created.",
    "Kilitlenen \xE7izim ve olu\u015Fturulan teklif revizyonu ge\xE7mi\u015Fte korunur. Sonraki de\u011Fi\u015Fiklikler yeni revizyonda yap\u0131l\u0131r.": "The locked drawing and quote revision remain in history. Further changes use a new revision.",
    "Cam \xF6l\xE7\xFCleri \xFCretim formunda hesaplan\u0131r. Tedarik\xE7iye \xF6zel sipari\u015F format\u0131 hen\xFCz tan\u0131mlanmam\u0131\u015Ft\u0131r.": "Glass sizes are calculated in the production form. A supplier-specific order format is not defined yet.",
    "Bu b\xF6l\xFCm ger\xE7ek stok miktar\u0131 i\xE7ermez. Planlanan stok i\u015F ak\u0131\u015F\u0131 hen\xFCz devreye al\u0131nmam\u0131\u015Ft\u0131r.": "This section does not show actual stock. The planned stock workflow is not active yet.",
    "V49 kayna\u011F\u0131nda bu \xFCr\xFCn i\xE7in optimizasyon devrede de\u011Fildir. Gelecekte ham profil baz\u0131nda hesaplanacakt\u0131r; RAL ve y\xFCzey kesim gruplama \xF6l\xE7\xFCt\xFC de\u011Fildir.": "Optimization is not active for this product. Future calculations will use raw profiles; RAL and finish do not define cutting groups.",
    "Bu \xFCretim paketi kaydedilmi\u015F ve salt okunurdur. De\u011Fi\u015Fiklik i\xE7in yeni proje revizyonu olu\u015Fturulmal\u0131d\u0131r.": "This production package is saved and read-only. Create a new project revision to make changes.",
