    "\xD6zel profilli \xE7at\u0131n\u0131n \xF6l\xE7\xFCs\xFCn\xFC \xE7izim yerle\u015Fim formundan d\xFCzenleyin. Kaynak geometri korunmu\u015Ftur.": "Edit custom-profile roof dimensions in the drawing layout form. Source geometry was kept.",
    "\xC7at\u0131 \xFCr\xFCn s\u0131n\u0131rlar\u0131na uygun de\u011Fil.": "The roof is outside the product limits.",
    "Ortak \xE7izim d\xFCzeni": "Shared Drawing Layout",
    "Bu eksendeki \xF6l\xE7\xFC yaln\u0131z ek profil s\u0131n\u0131r\u0131 \xFCzerinden de\u011Fi\u015Ftirilebilir.": "This axis dimension can be changed only through the additional profile boundary.",
    "Proje \xF6l\xE7\xFCleri geometri s\u0131n\u0131rlar\u0131na uygun de\u011Fil.": "Project dimensions exceed the geometry limits.",
    "Hareketi G\xF6ster": "Show Motion",
