    "\xC7izim kilitli veya salt okunur. \xD6nce \xC7izimi D\xFCzenle i\u015Flemini kullan\u0131n.": "The drawing is locked or read-only. Use Edit Drawing first.",
    "Tek i\u015Flemde ayn\u0131 \xFCr\xFCnden pozlar se\xE7in.": "Select positions from the same product in one operation.",
    "\xC7izim sahnesi zaman\u0131nda haz\u0131r olmad\u0131.": "The drawing scene was not ready in time.",
    "D\xFCzenlemek i\xE7in \xE7izim kilidini kald\u0131r\u0131n.": "Unlock the drawing to edit it.",
    "\xDCretim Formu": "Production Form",
    "Ge\xE7erli bir a\xE7\u0131 yaz\u0131n.": "Enter a valid angle.",
    "\xD6l\xE7\xFCler en az 500 mm, y\xFCkseklik en az 100 mm, k\xF6\u015Fe a\xE7\u0131s\u0131 30\u2013150\xB0 olmal\u0131.": "Dimensions must be at least 500 mm, height at least 100 mm and corner angle 30\u2013150\xB0.",
    "\xDCr\xFCn k\xF6\u015Fesi": "Product Corner",
    "Duvar k\xF6\u015Fesi": "Wall Corner",
    "Alan k\xF6\u015Fesi": "Area Corner",
    "Platform \xFCst\xFC": "Platform Top",
    "Par\xE7ay\u0131 Sil": "Delete Part",
    "Mesafe 0\u2013100000 mm aras\u0131nda olmal\u0131.": "Distance must be 0\u2013100000 mm.",
    "Bo\u015Fluk s\u0131n\u0131r\u0131": "Gap Boundary",
    "\xC7izim kilitli. \xD6nce \xE7izim kilidini kald\u0131r\u0131n.": "The drawing is locked. Unlock it first.",
    "Kayd\u0131rma mesafesi s\u0131f\u0131rdan b\xFCy\xFCk ve izin verilen a\xE7\u0131kl\u0131k i\xE7inde olmal\u0131.": "Offset must be positive and within the allowed opening.",
    "Dikme bir profil veya duvarla \xE7ak\u0131\u015F\u0131yor.": "The post overlaps a profile or wall.",
    "POZ B\u0130LG\u0130LER\u0130": "POSITION DETAILS",
    "Ayarlar\u0131 Resetle": "Reset Settings",
    "\u0130ki biti\u015Fik dikme se\xE7in.": "Select two adjacent posts.",
    "Bu kayd\u0131rma mevcut \xFCr\xFCne uygun alan b\u0131rakm\u0131yor.": "This offset leaves insufficient space for the existing product.",
    "B\xF6l\xFCnm\xFC\u015F her mod\xFCl en az 1000 mm geni\u015Flik ve 2104 mm a\xE7\u0131l\u0131m gerektirir.": "Each divided module needs at least 1000 mm width and 2104 mm projection.",
    "Bir yerle\u015Fimde en fazla 64 mod\xFCl olu\u015Fturulabilir.": "A layout can contain at most 64 modules.",
    "Parapet y\xFCksekli\u011Fi oluk alt kotunu a\u015Famaz.": "Parapet height cannot exceed the gutter underside level.",
    "Bu dosya ge\xE7erli bir Bioclimatic .plmr projesi de\u011Fil.": "This is not a valid Bioclimatic .plmr project file.",
    "Proje dosyas\u0131 en fazla 20 MB olabilir.": "The project file must not exceed 20 MB.",
    "Proje dosyas\u0131 okunamad\u0131; ge\xE7erli metin bekleniyor.": "The project file could not be read; valid text is required.",
    ".plmr uzant\u0131l\u0131 proje dosyas\u0131 se\xE7in.": "Select a .plmr project file.",
    "A\xE7\u0131kl\u0131k": "Opening",
    "Bu \xF6l\xE7\xFC de\u011Fi\u015Fikli\u011Fi biti\u015Fik ba\u011Flant\u0131lar\u0131 koruyam\u0131yor.": "This dimension change cannot preserve adjacent connections.",
    "Yeni \xF6l\xE7\xFC biti\u015Fik ba\u011Flant\u0131lar\u0131 korurken ba\u015Fka bir tavan pozuyla \xE7ak\u0131\u015F\u0131yor.": "The new dimension keeps adjacent connections but overlaps another roof position.",
    "Bu \xF6l\xE7\xFC de\u011Fi\u015Fikli\u011Fi biti\u015Fik yerle\u015Fime s\u0131\u011Fm\u0131yor.": "This dimension change does not fit the adjacent layout.",
    "Cephe en az 1000 mm, a\xE7\u0131l\u0131m en az 2104 mm ve ayak y\xFCksekli\u011Fi en az 1600 mm olmal\u0131d\u0131r.": "Facade width must be at least 1000 mm, projection 2104 mm and leg height 1600 mm.",
    "Profil kesiti se\xE7ilen a\xE7\u0131kl\u0131\u011Fa s\u0131\u011Fm\u0131yor; net mesafe negatif olamaz.": "The profile section does not fit the opening; clear distance cannot be negative.",
    "\u0130ki profil aras\u0131ndaki net mesafe 0 mm\u2019den d\xFC\u015F\xFCk olamaz.": "Clear distance between two profiles cannot be below 0 mm.",
    "Profil mevcut bir profille \xE7ak\u0131\u015F\u0131yor; net mesafe negatif olamaz.": "The profile overlaps an existing profile; clear distance cannot be negative.",
    "Bir ile be\u015F aras\u0131nda sahne se\xE7in.": "Select between one and five scenes.",
    "3D sahne hen\xFCz haz\u0131r de\u011Fil. Biraz sonra tekrar deneyin.": "The 3D scene is not ready yet. Try again shortly.",
    "3D sahne y\xFCklenemedi. Sayfay\u0131 yenileyip tekrar deneyin.": "The 3D scene could not be loaded. Refresh and try again.",
    "Sahnenin kamera a\xE7\u0131s\u0131 g\xFCncellendi.": "The scene camera angle was updated.",
    "Sahneleri Se\xE7": "Choose Scenes",
    "3D g\xF6r\xFCn\xFCm\xFC istedi\u011Finiz a\xE7\u0131ya \xE7evirin, ard\u0131ndan Mevcut A\xE7\u0131y\u0131 Ekle\u2019ye bas\u0131n. En fazla 5 a\xE7\u0131 se\xE7ebilirsiniz.": "Rotate the 3D view, then click Add Current View. You can choose up to 5 angles.",
    "Mevcut A\xE7\u0131y\u0131 Ekle": "Add Current View",
    "En fazla 5 sahne se\xE7ebilirsiniz.": "You can select up to 5 scenes.",
    "Kamera a\xE7\u0131s\u0131 eklendi. G\xF6r\xFCnt\xFC dosyas\u0131 olu\u015Fturulmad\u0131.": "Camera angle added. No image file was created.",
    "Sahne a\xE7\u0131lar\u0131 bu sekmede tutulur. PDF g\xF6r\xFCnt\xFClerinden ba\u011F\u0131ms\u0131zd\u0131r; sayfa yenilenirse yeniden se\xE7ilir.": "Scene angles stay in this tab, separately from PDF images. Select them again after a page reload.",
    "Ba\u015Flat": "Play",
    "Ba\u015Ftan": "Restart",
    "Ba\u011Flant\u0131, projenin \u015Fu anki durumunu g\xF6sterir. Sonradan yapt\u0131\u011F\u0131n\u0131z de\u011Fi\u015Fiklikler bu sunumu de\u011Fi\u015Ftirmez.": "The link shows the project\u2019s current state. Later edits do not change this presentation.",
    "Ba\u011Flant\u0131ya sahip ki\u015Filer 3D sunumu a\xE7abilir. G\xF6r\xFCnt\xFC veya video kaydedilmez.": "Anyone with the link can open the 3D presentation. No images or videos are recorded.",
    "Ba\u011Flant\u0131 se\xE7ildi. Kopyalay\u0131p payla\u015Fabilirsiniz.": "The link is selected. Copy and share it.",
    "Bu proje ba\u011Flant\u0131ya s\u0131\u011Fm\u0131yor. K\u0131sa ba\u011Flant\u0131 servisini ba\u011Flay\u0131n.": "This project is too large for an inline link. Connect the short-link service.",
    "Payla\u015F\u0131m servisine ula\u015F\u0131lamad\u0131. Ba\u011Flant\u0131 olu\u015Fturulmad\u0131; tekrar deneyin.": "The sharing service could not be reached. No link was created. Try again.",
    "K\u0131sa ba\u011Flant\u0131 servisi haz\u0131r de\u011Fil. Supabase kurulumunu tamamlay\u0131n.": "The short-link service is not ready. Complete Supabase setup.",
    "Sunum haz\u0131r. Bu ba\u011Flant\u0131 proje verisini i\xE7erdi\u011Fi i\xE7in uzundur. K\u0131sa ba\u011Flant\u0131 i\xE7in payla\u015F\u0131m servisi ba\u011Flanmal\u0131d\u0131r.": "The presentation is ready. This long link contains project data. Connect the sharing service for short links.",
    "Bu ba\u011Flant\u0131 i\xE7in g\xFCncel bir taray\u0131c\u0131 kullan\u0131n.": "Use a current browser for this link.",
