    "Bu taray\u0131c\u0131 cihazda \xE7eviriyi desteklemiyor. Metinleri her dil i\xE7in elle girebilirsiniz.": "This browser does not support on-device translation. You can enter texts manually for each language.",
    "Uygulamak, hedef dildeki mevcut metinlerin yerini al\u0131r. Kaynak ve kesinle\u015Fmi\u015F teklifler korunur.": "Applying replaces existing target-language texts. Source texts and finalized quotes are preserved.",
