    "\xC7eviri bo\u015F sonu\xE7 d\xF6nd\xFCrd\xFC. Metinler de\u011Fi\u015Ftirilmedi.": "Translation returned an empty result. Texts were not changed.",
    "dilindeki metinler. Her metin dili ayr\u0131 kaydedilir. Teklifin dilinde metin yoksa varsay\u0131lan dildeki metin kullan\u0131l\u0131r.": " texts. Each text language is saved separately. If the quote language has no text, the default-language text is used.",
    "Kaynak, yukar\u0131da se\xE7ilen metin dilidir. \u0130ngilizce kaynak kullanabilirsiniz. \xC7eviri cihaz\u0131n\u0131zda haz\u0131rlan\u0131r; ilk kullan\u0131mda taray\u0131c\u0131 dil paketi indirebilir. Sonucu kontrol edip uygulay\u0131n, ard\u0131ndan Kaydet ve Kilitle ile kaydedin.": "The source is the text language selected above. You can use English as the source. Translation runs on your device; the browser may download a language pack on first use. Review and apply the result, then Save and Lock.",
